import Foundation

/// `ServerCertificateTests`의 고정 인증서. `tailnet certificate-fixtures`(`Tools/interop/cmd/tailnet/derpcert.go`)가
/// 만든 것을 그대로 옮겼다(README "인증서 고정값"). 키와 서명은 난수라 다시 만들면 바이트가 바뀐다.
///
/// 자체 서명 인증서들의 유효 기간은 2026-01-01T00:00:00Z ..< 2027-01-01T00:00:00Z다(`meta` 빼고).
enum ServerCertificateFixtures {
    /// derper의 수동 인증서 모드와 같은 모양의 자체 서명 인증서. CN과 IP SAN이 `100.64.0.1`이다.
    static let ipLeaf = der("")
    /// `ipLeaf`와 같은 모양, 다른 키의 인증서.
    static let otherIPLeaf = der("")
    /// 같은 모양에 SAN을 DNS 이름 `derp1a.example.test`로 바꾼 자체 서명 인증서.
    static let dnsLeaf = der("")
    /// `namedLeaf`를 발급한 시험 루트(CA).
    static let root = der("")
    /// `root`가 발급한 `derp-cert.example.test` 인증서.
    static let namedLeaf = der("")
    /// 실제 `derpserver.Server.MetaCert()`. 주체 CN이 `derpkey<서버 공개 키 16진>`인 Ed25519 자체 서명 인증서다.
    static let meta = der("")
    /// `ipLeaf` DER의 SHA-256(Go `fmt.Sprintf("%02x", sha256.Sum256(der))`).
    static let ipLeafSHA256 = "784f7cbb4b718afea8f9a6185505830fc85631cf7b6acc4945e62b4476e9af6d"
    /// `dnsLeaf` DER의 SHA-256.
    static let dnsLeafSHA256 = "853a422f459bc838706d4fc27eb6415ac6acc805d09aead3972eff0618fd048e"
    /// `meta` DER의 SHA-256.
    static let metaSHA256 = "f56196d35a64cf272d58f316004c412c08c03e63d5168fa1f12f9921a8a8de5c"

    private static func der(_ base64: String) -> [UInt8] {
        guard let data = Data(base64Encoded: base64) else { preconditionFailure("고정 인증서의 base64가 틀렸다") }
        return [UInt8](data)
    }
}
